unsigned hash(const char *k) {
    unsigned h = 5381;
    for (; *k; k++) h = h * 33 + (unsigned char)*k;
    return h % BUCKETS;
}

void put(const char *k, int v) {
    unsigned i = hash(k);
    struct Node *n = malloc(sizeof(struct Node));
    strncpy(n->key, k, 31); n->key[31] = 0; n->val = v; n->next = table[i];
    table[i] = n;
}

int get(const char *k, int *out) {
    for (struct Node *n = table[hash(k)]; n; n = n->next)
        if (strcmp(n->key, k) == 0) { *out = n->val; return 1; }
    return 0;
}

